commands.command:
set -euo pipefail
git fetch origin work/photomap-straighten-20260912
test "$(git rev-parse HEAD)" = "d6288d0e3488d7fb51da29e5ee5bd7ec9f773cbc"
test "$(git rev-parse origin/work/photomap-straighten-20260912)" = "d6288d0e3488d7fb51da29e5ee5bd7ec9f773cbc"
test -z "$(git status --porcelain)"
python3 - <<'PY'
from pathlib import Path

p = Path('frontend/src/components/admin/useAdminPanelData.ts')
s = p.read_text()
s = s.replace('''  const refreshAll = useCallback(async () => {
    await Promise.all([
      refreshAppConfig(),
      refreshCategories(),
      refreshCities(),
      refreshGuides(),
      refreshMemories("pending"),
      refreshModerationCounts(),
      refreshPlaces(),
      refreshReports("open"),
    ]);
    setAccessMessage(null);
    setLoadError(null);
  }, [
    refreshAppConfig,
    refreshCategories,
    refreshCities,
    refreshGuides,
    refreshMemories,
    refreshModerationCounts,
    refreshPlaces,
    refreshReports,
  ]);
''','''  const refreshInitialData = useCallback(async () => {
    await Promise.all([
      refreshAppConfig(),
      refreshCategories(),
      refreshCities(),
      refreshModerationCounts(),
      refreshPlaces(),
    ]);
    setAccessMessage(null);
    setLoadError(null);
  }, [refreshAppConfig, refreshCategories, refreshCities, refreshModerationCounts, refreshPlaces]);
''',1)
s = s.replace('''  const refreshGuidesResult = useCallback(async () => {
    await refreshGuides();
  }, [refreshGuides]);
''','''  const refreshGuidesResult = useCallback(async () => {
    try {
      await refreshGuides();
    } catch (reason) {
      setLoadError(adminLoadError(reason));
      throw reason;
    }
  }, [refreshGuides]);
''',1)
s = s.replace('refreshAll().catch((reason: unknown) => {','refreshInitialData().catch((reason: unknown) => {',1)
s = s.replace('[adminToken, refreshAll, resetData]','[adminToken, refreshInitialData, resetData]',1)
if 'const refreshAll' in s or 'refreshAll().catch' in s:
    raise SystemExit('useAdminPanelData replacement incomplete')
p.write_text(s)

p = Path('frontend/src/pages/AdminPlacesPage.tsx')
s = p.read_text()
anchor = 'import { useAdminSectionState } from "../components/admin/useAdminSectionState";\n'
if 'useAdminSectionDataLoader' not in s:
    if anchor not in s:
        raise SystemExit('AdminPlacesPage import anchor missing')
    s = s.replace(anchor, anchor + 'import { useAdminSectionDataLoader } from "../components/admin/useAdminSectionDataLoader";\n', 1)
anchor = '  const placeRefreshActions = useAdminPlaceRefreshActions({\n'
if '  useAdminSectionDataLoader({' not in s:
    if anchor not in s:
        raise SystemExit('AdminPlacesPage loader anchor missing')
    s = s.replace(anchor, '''  useAdminSectionDataLoader({
    activeModerationSection,
    activeSection,
    adminToken,
    memoryStatusFilter,
    refreshGuides,
    refreshMemories,
    refreshReports,
    reportStatusFilter,
  });

''' + anchor, 1)
s = s.replace('''  function handleMemoryStatusFilterChange(status: typeof memoryStatusFilter) {
    setMemoryStatusFilter(status);
    refreshMemories(status).catch(() => undefined);
  }

  function handleReportStatusFilterChange(status: typeof reportStatusFilter) {
    setReportStatusFilter(status);
    refreshReports(status).catch(() => undefined);
  }
''','''  function handleMemoryStatusFilterChange(status: typeof memoryStatusFilter) {
    setMemoryStatusFilter(status);
  }

  function handleReportStatusFilterChange(status: typeof reportStatusFilter) {
    setReportStatusFilter(status);
  }
''',1)
p.write_text(s)
PY
cd frontend
npm run lint
npm run build
cd ..
VENV=$(mktemp -d /tmp/photomap-admin-e2e-XXXXXX)
trap 'rm -rf "$VENV"; ./scripts/devctl.sh stop >/dev/null 2>&1 || true' EXIT
python3 -m venv "$VENV"
"$VENV/bin/python" -m pip install -q -r backend/requirements.txt
cd frontend
PYTHON="$VENV/bin/python" npm run test:e2e -- e2e/visual/admin-lazy-loading.spec.ts e2e/visual/admin.spec.ts --project=chromium --grep-invert 'visual:'
cd ..
git diff --check
git status --short
git add frontend/src/components/admin/useAdminPanelData.ts frontend/src/pages/AdminPlacesPage.tsx
git commit -m 'Load admin section data on demand'
git push origin HEAD:work/photomap-straighten-20260912
printf 'published_sha=' && git rev-parse HEAD
